def fetch_maintenance_records(api_url: str, aircraft_id: str) -> list[dict[str, object]]:
    if not aircraft_id.strip():
        raise ValueError('aircraft_id must not be blank')
    url = f"{api_url.rstrip('/')}/aircraft/{aircraft_id}/maintenance"
