import json

def serialize_state(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def screen_state(payload: bytes, denied_countries: set[str]) -> list[dict]:
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid state')
    if not isinstance(value, list):
        raise ValueError('invalid state')
    for record in value:
        if not isinstance(record, dict) or not isinstance(record.get('reference'), str) or (not isinstance(record.get('country'), str)) or (not isinstance(record.get('amount'), (int, float))) or isinstance(record.get('amount'), bool):
            raise ValueError('invalid state')
    result = [record for record in value if record['country'].upper() not in denied_countries]
    return sorted(result, key=lambda record: record['amount'], reverse=True)

