import json
import urllib.request

def fetch_lounges(airport_code: str, minimum_rating: float) -> list[dict[str, object]]:
    if len(airport_code) != 3 or not airport_code.isascii() or (not airport_code.isupper()) or (not airport_code.isalpha()):
        raise ValueError('invalid airport code')
    if not 0 <= minimum_rating <= 5:
        raise ValueError('invalid minimum rating')
    url = 'https://lounge.example.test/api/lounges?airport=' + airport_code
    with urllib.request.urlopen(url) as response:
        lounges = json.loads(response.read().decode('utf-8'))['lounges']
    selected = [lounge for lounge in lounges if lounge['rating'] >= minimum_rating]
    return sorted(selected, key=lambda lounge: (-lounge['rating'], lounge['name']))

