import json
from unittest.mock import MagicMock, patch


def make_response(payload):
    response = MagicMock()
    response.__enter__.return_value = response
    response.__exit__.return_value = False
    response.read.return_value = json.dumps(payload).encode("utf-8")
    return response


def test_counts_statuses_and_sorts_keys():
    response = make_response({
        "documents": [
            {"status": "review"},
            {"status": "privileged"},
            {"status": "review"},
            {"status": "production"},
            {"status": "privileged"},
        ]
    })
    with patch("solution.urllib.request.urlopen", return_value=response) as opener:
        result = fetch_document_status_counts("https://review.example/api", "case-7")

    assert result == {"privileged": 2, "production": 1, "review": 2}
    assert opener.call_args[0][0] == "https://review.example/api/cases/case-7/documents"


def test_empty_document_list_returns_empty_dictionary():
    response = make_response({"documents": []})
    with patch("solution.urllib.request.urlopen", return_value=response):
        result = fetch_document_status_counts("https://review.example/api/", "alpha")

    assert result == {}


def test_case_id_is_encoded_as_one_path_segment():
    response = make_response({"documents": [{"status": "review"}]})
    with patch("solution.urllib.request.urlopen", return_value=response) as opener:
        result = fetch_document_status_counts("https://review.example", "case 7/blue")

    assert result == {"review": 1}
    assert opener.call_args[0][0] == "https://review.example/cases/case%207%2Fblue/documents"


def test_blank_case_id_raises_value_error_without_request():
    with patch("solution.urllib.request.urlopen") as opener:
        try:
            fetch_document_status_counts("https://review.example", "   ")
        except ValueError:
            pass
        else:
            assert False

    opener.assert_not_called()

