def encode_campaign(state: dict[str, object]) -> bytes:
    return json.dumps(state, separators=(',', ':')).encode('utf-8')

def load_campaign(payload: bytes) -> list[dict[str, object]]:
    try:
        state = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid campaign payload')
    if not isinstance(state, dict) or not isinstance(state.get('campaign'), str):
        raise ValueError('invalid campaign state')
    quests = state.get('quests')
    if not isinstance(quests, list):
        raise ValueError('invalid quest list')
    for quest in quests:
        if not isinstance(quest, dict):
            raise ValueError('invalid quest')
        if not isinstance(quest.get('title'), str):
            raise ValueError('invalid quest title')
        if not isinstance(quest.get('status'), str):
            raise ValueError('invalid quest status')
        if not isinstance(quest.get('reward'), int) or isinstance(quest.get('reward'), bool):
            raise ValueError('invalid quest reward')
    return sorted([quest for quest in quests if quest['status'] == 'active'], key=lambda quest: (-quest['reward'], quest['title']))

