import json

def _validate(session):
    if not isinstance(session, dict):
        raise ValueError('invalid session')
    if not isinstance(session.get('player_id'), str) or not session['player_id']:
        raise ValueError('invalid session')
    if not isinstance(session.get('level'), int) or isinstance(session['level'], bool):
        raise ValueError('invalid session')
    if not isinstance(session.get('inventory'), list) or not all((isinstance(item, str) for item in session['inventory'])):
        raise ValueError('invalid session')
    if not isinstance(session.get('updated_at'), int) or isinstance(session['updated_at'], bool):
        raise ValueError('invalid session')
    return session

def dump_session(session: dict) -> bytes:
    _validate(session)
    return json.dumps(session, separators=(',', ':'), sort_keys=True).encode('utf-8')

def load_session(blob: bytes) -> dict:
    try:
        session = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid session payload') from exc
    return _validate(session)

