def pack_invoices(invoices: list[dict]) -> bytes:
    return json.dumps(invoices, separators=(',', ':')).encode('utf-8')

def load_invoices(payload: bytes) -> list[dict]:
    try:
        invoices = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid invoice payload') from exc
    if not isinstance(invoices, list):
