        due_days = invoice.get('due_days')
        if isinstance(due_days, bool) or not isinstance(due_days, int) or due_days < 0:
            raise ValueError('invalid due_days')
    return sorted(invoices, key=lambda item: (-item['amount'], item['invoice_id']))

