import json
import urllib.request

def list_devices(api_url: str, minimum_battery: int) -> list[dict]:
    if not 0 <= minimum_battery <= 100:
        raise ValueError('minimum_battery must be between 0 and 100')
    url = api_url.rstrip('/') + '/v1/devices'
    with urllib.request.urlopen(url) as response:
        payload = json.loads(response.read().decode('utf-8'))
    devices = [device for device in payload['devices'] if device['battery'] >= minimum_battery]
    return sorted(devices, key=lambda device: device['name'])

