def dump_portfolio(portfolio: dict[str, float]) -> bytes:
    return json.dumps(portfolio, sort_keys=True, separators=(',', ':')).encode('utf-8')

def load_portfolio(data: bytes) -> dict[str, float]:
    try:
        portfolio = json.loads(data.decode('utf-8'))
    except (UnicodeDecodeError, ValueError) as exc:
        raise ValueError('invalid portfolio data') from exc
    if not isinstance(portfolio, dict):
        raise ValueError('portfolio must be a mapping')
    for ticker, amount in portfolio.items():
        if not isinstance(ticker, str) or not isinstance(amount, Real) or isinstance(amount, bool) or (amount < 0):
            raise ValueError('invalid portfolio entry')
    return portfolio

def rebalance(holdings: dict[str, float], target_weights: dict[str, float], total_value: float) -> dict[str, float]:
    if total_value < 0 or any((value < 0 for value in holdings.values())) or any((value < 0 for value in target_weights.values())):
        raise ValueError('values must be nonnegative')
    if abs(sum(target_weights.values()) - 1.0) > 1e-09:
        raise ValueError('target weights must sum to one')
    tickers = sorted(set(holdings) | set(target_weights))
    return {ticker: round(target_weights.get(ticker, 0.0) * total_value - holdings.get(ticker, 0.0), 2) for ticker in tickers}

