import json
import urllib.parse
import urllib.request

def fetch_classes(day: str) -> list[dict]:
    days = {'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'}
    if day not in days:
        raise ValueError('invalid day')
    query = urllib.parse.urlencode({'day': day})
    url = 'https://fitness.example.test/classes?' + query
    with urllib.request.urlopen(url) as response:
        payload = json.loads(response.read().decode('utf-8'))
    classes = [item for item in payload['classes'] if item['day'] == day]
    return sorted(classes, key=lambda item: item['start'])

