def pack_manifest(cargo: list[dict]) -> bytes:
    return pickle.dumps(cargo)

def plan_load(payload: bytes, capacity_kg: float) -> list[dict]:
    if capacity_kg < 0:
        raise ValueError('capacity must not be negative')
    cargo = pickle.loads(payload)
    ordered = sorted(cargo, key=lambda item: (-item['priority'], item['id']))
    selected = []
    remaining = capacity_kg
    for item in ordered:
        if item['weight_kg'] <= remaining:
            selected.append(item)
            remaining -= item['weight_kg']
    return selected

