from solution import compare_tariffs

import json
from unittest.mock import MagicMock, patch


def make_response(payload):
    response = MagicMock()
    response.__enter__.return_value = response
    response.__exit__.return_value = False
    response.read.return_value = json.dumps(payload).encode("utf-8")
    return response


def test_filters_and_sorts_tariffs():
    payload = {
        "tariffs": [
            {"provider": "Green Power", "unit_rate": 0.31, "available": True},
            {"provider": "City Energy", "unit_rate": 0.22, "available": True},
            {"provider": "Old Utility", "unit_rate": 0.15, "available": False},
        ]
    }
    with patch("solution.urllib.request.urlopen", return_value=make_response(payload)) as opened:
        result = compare_tariffs("https://utility.example/tariffs", "AB 12CD")

    assert result == [
        {"provider": "City Energy", "unit_rate": 0.22, "available": True},
        {"provider": "Green Power", "unit_rate": 0.31, "available": True},
    ]
    assert opened.call_args[0][0] == "https://utility.example/tariffs?postcode=AB+12CD"


def test_postcode_is_encoded_in_requested_url():
    payload = {"tariffs": []}
    with patch("solution.urllib.request.urlopen", return_value=make_response(payload)) as opened:
        result = compare_tariffs("https://utility.example/compare", "M1/2&Q")

    assert result == []
    assert opened.call_args[0][0] == "https://utility.example/compare?postcode=M1%2F2%26Q"


def test_preserves_extra_tariff_fields_and_equal_rate_order():
    first = {"provider": "A", "unit_rate": 0.2, "available": True, "region": "north"}
    second = {"provider": "B", "unit_rate": 0.2, "available": True, "region": "south"}
    with patch("solution.urllib.request.urlopen", return_value=make_response({"tariffs": [first, second]})):
        result = compare_tariffs("https://utility.example/tariffs", "ZZ9 9ZZ")

    assert result == [first, second]


def test_rejects_response_without_tariff_list():
    with patch("solution.urllib.request.urlopen", return_value=make_response({"items": []})):
        try:
            compare_tariffs("https://utility.example/tariffs", "AB1 2CD")
        except ValueError:
            pass
        else:
            assert False

