import json

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be an object')
        if set(record) != {'id', 'product', 'message', 'severity'}:
            raise ValueError('invalid record fields')
        if not all((isinstance(record[name], str) for name in ('id', 'product', 'message'))):
            raise ValueError('text fields must be strings')
        if isinstance(record['severity'], bool) or not isinstance(record['severity'], int) or (not 1 <= record['severity'] <= 5):
            raise ValueError('invalid severity')
    return sorted(records, key=lambda record: (-record['severity'], record['id']))

def encode_recalls(recalls: list[dict[str, object]]) -> bytes:
    _validate(recalls)
    return json.dumps(recalls, separators=(',', ':')).encode('utf-8')

def decode_recalls(payload: bytes) -> list[dict[str, object]]:
    try:
        records = json.loads(payload.decode('utf-8'))
        return _validate(records)
    except (UnicodeError, json.JSONDecodeError, TypeError, ValueError) as error:
        if isinstance(error, ValueError) and str(error) in {'records must be a list', 'record must be an object', 'invalid record fields', 'text fields must be strings', 'invalid severity'}:
            raise
        raise ValueError('invalid payload') from error

