import html

def render_maintenance_table(records: list[dict[str, str]]) -> str:
    required = ('vehicle', 'service', 'due_km', 'status')
    rows = []
    for record in records:
        if any((field not in record for field in required)):
            raise ValueError('missing field')
        try:
            due_number = int(record['due_km'])
        except (TypeError, ValueError):
            raise ValueError('invalid due_km')
        if record['status'] != 'completed':
            rows.append((due_number, record))
    rows.sort(key=lambda item: item[0])
    body = ''.join(('<tr><td>' + html.escape(str(record['vehicle'])) + '</td><td>' + html.escape(str(record['service'])) + '</td><td>' + html.escape(str(record['due_km'])) + '</td><td>' + html.escape(str(record['status'])) + '</td></tr>' for _, record in rows))
    return '<table><thead><tr><th>Vehicle</th><th>Service</th><th>Due (km)</th><th>Status</th></tr></thead>' + '<tbody>' + body + '</tbody></table>'

