import html

def render_translation_table(rows: list[tuple[str, str, str]], status_filter: str | None=None) -> str:
    allowed = {'draft', 'review', 'approved'}
    if status_filter is not None and status_filter not in allowed:
        raise ValueError('invalid status filter')
    selected = [row for row in rows if status_filter is None or row[1] == status_filter]
    selected.sort(key=lambda row: (row[0], row[2]))
    parts = ['<table class="translations"><thead><tr><th>Locale</th><th>Status</th><th>Text</th></tr></thead><tbody>']
    for locale, status, text in selected:
        parts.append(f'<tr><td>{html.escape(locale, quote=True)}</td><td>{html.escape(status, quote=True)}</td><td>{html.escape(text, quote=True)}</td></tr>')
    parts.append('</tbody></table>')
    return ''.join(parts)

