    return json.dumps({'message': message, 'signature': signature}, separators=(',', ':')).encode('utf-8')

def verify_signed_blob(blob: bytes, key: bytes) -> bool:
    try:
        record = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, AttributeError):
        try:
            record = pickle.loads(blob)
        except Exception:
            raise ValueError('invalid payload')
    if not isinstance(record, dict):
        raise ValueError('invalid payload')
    message = record.get('message')
    signature = record.get('signature')
    if not isinstance(message, str) or not isinstance(signature, str):
        raise ValueError('invalid payload')
    expected = hmac.new(key, message.encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

