import urllib.request

def fetch_pending_applications(api_url: str, minimum_amount: float) -> list[dict]:
    if minimum_amount < 0:
        raise ValueError('minimum_amount must not be negative')
    url = api_url.rstrip('/') + '/applications?status=pending'
    with urllib.request.urlopen(url) as response:
        data = json.loads(response.read().decode('utf-8'))
    applications = [application for application in data['applications'] if application['status'] == 'pending' and application['amount'] >= minimum_amount]
    return sorted(applications, key=lambda application: (-application['amount'], application['applicant_id']))

