import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _value(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left, right = (_value(node.left, names), _value(node.right, names))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _value(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _value(child, names)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        for op, child in zip(node.ops, node.comparators):
            right = _value(child, names)
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, names) for x in node.args])
    raise ValueError('invalid rule')

def select_deliveries(deliveries: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        tree = ast.parse(rule, mode='eval')
        selected = [item for item in deliveries if _value(tree.body, item)]
    except Exception as exc:
        raise ValueError('invalid rule') from exc
    return sorted(selected, key=lambda item: (item['eta'], item['id']))

