import math

def parse_noise_report(report: str, secret: str) -> tuple[str, float]:
    parts = report.split('|')
    if len(parts) != 3:
        raise ValueError('invalid report')
    station, level_text, signature = parts
    if not station:
        raise ValueError('invalid station')
    try:
        level = float(level_text)
    except ValueError as exc:
        raise ValueError('invalid level') from exc
    if not math.isfinite(level) or not 0 <= level <= 200:
        raise ValueError('invalid level')
    message = f'{station}|{level_text}'.encode()
    expected = hmac.new(secret.encode(), message, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    return (station, level)

