import tempfile

def export_scan_report(findings: list[dict[str, str]], output_path: str) -> int:
    allowed = {'critical', 'high', 'medium', 'low'}
    for finding in findings:
        if finding['severity'] not in allowed:
            raise ValueError('invalid severity')
    selected = [f for f in findings if f['severity'] in {'critical', 'high'}]
    selected.sort(key=lambda f: (0 if f['severity'] == 'critical' else 1, f['image'], f['package']))
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(dir=parent, prefix='.scan-')
    os.close(fd)
    try:
        with open(temporary_path, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['image', 'package', 'severity', 'fixed_version'])
            for finding in selected:
                writer.writerow([finding['image'], finding['package'], finding['severity'], finding['fixed_version']])
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return len(selected)

