def aggregate_health(requester: dict, checks: list[dict]) -> dict:
    required = {'service', 'tenant_id', 'owner_id', 'status', 'latency_ms'}
    selected = []
    for check in checks:
        if not required.issubset(check):
            raise ValueError('missing check field')
        if check['latency_ms'] < 0:
            raise ValueError('negative latency')
        allowed = check['owner_id'] == requester['id'] or (check['tenant_id'] == requester['tenant_id'] and 'operator' in requester.get('roles', []))
        if allowed:
            selected.append(check)
    healthy = sum((check['status'] == 'healthy' for check in selected))
    total = len(selected)
    average = round(sum((check['latency_ms'] for check in selected)) / total, 2) if total else 0.0
    return {'total': total, 'healthy': healthy, 'unhealthy': total - healthy, 'average_latency_ms': average, 'services': sorted((check['service'] for check in selected))}

