import subprocess

def find_jurors(roster_path: str, district: str) -> list[str]:
    result = subprocess.run(['grep', '-i', '-F', '--', district, roster_path], capture_output=True, text=True, check=False)
    if result.returncode == 2:
        raise OSError(result.stderr.strip() or 'grep failed')
    names = []
    for line in result.stdout.splitlines():
        if not line.strip() or line.count('|') != 1:
            continue
        name, found_district = line.split('|', 1)
        if found_district.casefold() == district.casefold():
            names.append(name)
    return sorted(names, key=str.casefold)

