import hashlib
import hmac
import os

def hash_token(token: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', token.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_token(token: str, stored: str) -> bool:
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', token.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

def eligible_rates(rates: dict[str, float], minimum: float) -> list[tuple[str, float]]:
    if minimum < 0:
        raise ValueError('minimum must not be negative')
    return sorted(((code, rate) for code, rate in rates.items() if rate >= minimum), key=lambda item: item[0])

