def parse_crypto_transactions(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    transactions = []
    for item in root.findall('transaction'):
        transactions.append({'date': item.attrib['date'], 'asset': item.attrib['asset'], 'amount': float(item.findtext('amount', '')), 'fiat_value': float(item.findtext('fiatValue', ''))})
