import io
import xml.sax
import xml.sax.handler

class _TransactionHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.transactions = []
        self.current = None
        self.field = None
        self.text = []

    def startElement(self, name, attrs):
        if name == 'transaction':
            self.current = {'date': attrs['date'], 'asset': attrs['asset']}
        elif self.current is not None and name in ('amount', 'fiatValue'):
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.current is not None and name == self.field:
            key = 'fiat_value' if name == 'fiatValue' else name
            self.current[key] = float(''.join(self.text).strip())
            self.field = None
        elif name == 'transaction' and self.current is not None:
            self.transactions.append(self.current)
            self.current = None

def parse_crypto_transactions(xml_text: str) -> list[dict]:
    handler = _TransactionHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, KeyError, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    handler.transactions.sort(key=lambda item: item['date'])
    return handler.transactions

