def filter_shelters(shelters: list[dict], rule: str) -> list[dict]:
    tree = ast.parse(rule, mode='eval').body

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            return ops[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp):
            value = evaluate(node.operand, values)
            return {ast.USub: operator.neg, ast.UAdd: operator.pos, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp):
            vals = [evaluate(x, values) for x in node.values]
            return all(vals) if isinstance(node.op, ast.And) else any(vals)
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            results = []
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, values)
                results.append({ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right))
                left = right
            return all(results)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
            args = [evaluate(x, values) for x in node.args]
            if len(args) < 2:
                raise ValueError('min/max requires at least two arguments')
            return min(args) if node.func.id == 'min' else max(args)
        raise ValueError('unsupported rule')
    selected = []
