        values = {key: shelter[key] for key in ('name', 'capacity', 'occupied', 'priority')}
        if evaluate(tree, values):
            selected.append(shelter)
    return sorted(selected, key=lambda item: item['capacity'] - item['occupied'], reverse=True)

