    try:
        salt_text, expected = stored_pin_hash.split('$')
        salt = bytes.fromhex(salt_text)
        actual = hashlib.sha256(salt + pin.encode()).hexdigest()
        matches = actual == expected
    except (AttributeError, ValueError, UnicodeError):
        return False
    if not matches:
        return False
    if any((not isinstance(price, int) or isinstance(price, bool) or price <= 0 for price in item_prices)):
        return False
    return sum(item_prices) == charged_coins

