import hashlib
import hmac
from urllib.parse import parse_qs

def verify_schedule_request(payload: str, signature: str, secret: bytes) -> dict[str, object]:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        fields = parse_qs(payload, keep_blank_values=True, strict_parsing=True)
    except ValueError as exc:
        raise ValueError('invalid payload') from exc
    if set(fields) != {'worker', 'date', 'hours'} or any((len(values) != 1 for values in fields.values())):
        raise ValueError('invalid fields')
    worker = fields['worker'][0]
    date = fields['date'][0]
    hours_text = fields['hours'][0]
    if not worker:
        raise ValueError('invalid worker')
    try:
        datetime.date.fromisoformat(date)
        hours = int(hours_text)
    except ValueError as exc:
        raise ValueError('invalid schedule') from exc
    if not 1 <= hours <= 24:
        raise ValueError('invalid hours')
    return {'worker': worker, 'date': date, 'hours': hours}

