        raise ValueError('limit must not be negative')
    selected = [trip for trip in trips if _evaluate(rule, {'price': trip['price'], 'days': trip['days'], 'rating': trip['rating']})]
    selected.sort(key=lambda trip: (trip['price'], -trip['rating']))
    return selected[:limit]

