import os

def create_access_request(subject_id: str, pin: str) -> dict[str, str]:
    subject_id = subject_id.strip()
    if not subject_id or len(pin) != 4 or (not pin.isdecimal()):
        raise ValueError('invalid request')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'subject_id': subject_id, 'pin_record': salt.hex() + ':' + digest.hex()}

def verify_access_request(request: dict[str, str], pin: str) -> bool:
    record = request.get('pin_record')
    if not isinstance(record, str) or not isinstance(pin, str):
        return False
    try:
        salt_text, digest_text = record.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

