    for sample in samples:
        if sample['id'] == sample_id:
            same_tenant = requester['tenant_id'] == sample['tenant_id']
            is_owner = requester['user_id'] == sample['owner_id']
            is_manager = 'lab_manager' in requester.get('roles', [])
