import hashlib
import hmac
import re

def verify_payment(payload: str, secret: str) -> dict:
    parts = payload.split('&')
    if len(parts) != 3 or not parts[0].startswith('plate=') or (not parts[1].startswith('minutes=')) or (not parts[2].startswith('sig=')):
        raise ValueError('invalid payload')
    plate = parts[0][6:]
    minutes_text = parts[1][8:]
    signature = parts[2][4:]
    if not re.fullmatch('[A-Z0-9]{1,8}', plate):
        raise ValueError('invalid plate')
    try:
        minutes = int(minutes_text)
    except ValueError:
        raise ValueError('invalid minutes')
    if not 1 <= minutes <= 240:
        raise ValueError('invalid minutes')
    body = f'plate={plate}&minutes={minutes_text}'
    expected = hmac.new(secret.encode('utf-8'), body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    return {'plate': plate, 'minutes': minutes}

