import ast
import operator

def filter_market_news(articles: list[dict], rule: str) -> list[str]:
    tree = ast.parse(rule, mode='eval')
    allowed_names = {'change_pct', 'volume_ratio', 'sentiment'}
    functions = {'abs': abs, 'min': min, 'max': max, 'round': round}

    def evaluate(node, values):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, values)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in allowed_names:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            left = evaluate(node.left, values)
            right = evaluate(node.right, values)
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            value = evaluate(node.operand, values)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
            result = evaluate(node.values[0], values)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(item, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            checks = []
            for op, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator, values)
                checks.append({ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right))
                left = right
            return all(checks)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in functions):
            return functions[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('unsupported expression')
    return [article['headline'] for article in articles if evaluate(tree, article)]

