import base64
import hashlib
import hmac
import os

def create_budget_profile(username: str, password: str, monthly_limit: float) -> dict:
    username = username.strip()
    if not username or len(password) < 4 or monthly_limit < 0:
        raise ValueError('invalid profile')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    record = base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()
    return {'username': username, 'monthly_limit': float(monthly_limit), 'password_record': record}

def authenticate_budget_profile(profile: dict, password: str) -> bool:
    if not isinstance(password, str):
        return False
    try:
        salt_text, digest_text = profile['password_record'].split(':', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

