import hashlib
import hmac

def parse_dispatch_update(message: str, signature: str, key: str) -> dict | None:
    expected = hmac.new(key.encode(), message.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    fields = message.split(',')
    if len(fields) != 3:
        raise ValueError('invalid update')
    courier_id, eta_text, zone = fields
    if not courier_id or not zone:
        raise ValueError('invalid update')
    try:
        eta_minutes = int(eta_text)
    except ValueError:
        raise ValueError('invalid update')
    if eta_minutes < 0:
        raise ValueError('invalid update')
    return {'courier_id': courier_id, 'eta_minutes': eta_minutes, 'zone': zone}

