import ast

def _evaluate(rule, values):
    try:
        node = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc

    def visit(n):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in values:
                raise NameError(n.id)
            return values[n.id]
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(n.operand)
            return +value if isinstance(n.op, ast.UAdd) else -value if isinstance(n.op, ast.USub) else not value
        if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (visit(n.left), visit(n.right))
            if isinstance(n.op, ast.Add):
                return left + right
            if isinstance(n.op, ast.Sub):
                return left - right
            if isinstance(n.op, ast.Mult):
                return left * right
            return left / right
        if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
            result = visit(n.values[0])
            for item in n.values[1:]:
                if isinstance(n.op, ast.And) and (not result):
                    return result
                if isinstance(n.op, ast.Or) and result:
                    return result
                result = visit(item)
            return result
        if isinstance(n, ast.Compare):
            left = visit(n.left)
            for op, item in zip(n.ops, n.comparators):
                right = visit(item)
                if not isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)):
                    raise ValueError('invalid rule')
                passed = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
                if not passed:
                    return False
                left = right
            return True
        raise ValueError('invalid rule')
    return visit(node)

def factor_invoices(invoices: list[dict[str, object]], rule: str) -> dict[str, object]:
    selected = []
    for invoice in invoices:
        values = {name: invoice[name] for name in ('amount', 'days_outstanding', 'risk_score')}
        values['id'] = invoice['id']
        if _evaluate(rule, values):
            selected.append(invoice)
    selected.sort(key=lambda invoice: invoice['amount'], reverse=True)
    return {'invoice_ids': [invoice['id'] for invoice in selected], 'total_amount': sum((invoice['amount'] for invoice in selected))}

