import hmac
import json

def process_matter_webhook(payload: str, signature: str, secret: str) -> dict:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, ValueError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict):
        raise ValueError('invalid payload')
    matter_id = data.get('matter_id')
    event = data.get('event')
    timestamp = data.get('timestamp')
    if not isinstance(matter_id, str) or not matter_id:
        raise ValueError('invalid matter_id')
    if not isinstance(event, str) or not event:
        raise ValueError('invalid event')
    if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
        raise ValueError('invalid timestamp')
    return {'matter_id': matter_id, 'event': event, 'timestamp': timestamp}

