import xml.etree.ElementTree as ET

def parse_load_plan(xml_text: str) -> list[tuple[str, str, float]]:
    try:
        root = ET.fromstring(xml_text)
        if root.tag != 'load_plan':
            raise ValueError('invalid root')
        result = []
        for cargo in root:
            if cargo.tag != 'cargo':
                continue
            weight = float(cargo.attrib['weight'])
            if weight <= 0:
                raise ValueError('weight must be positive')
            result.append((cargo.attrib['id'], cargo.attrib['destination'], weight))
        result.sort(key=lambda item: item[2], reverse=True)
        return result
    except ValueError:
        raise
    except (ET.ParseError, KeyError, TypeError) as exc:
        raise ValueError('invalid load plan') from exc

