import json

def verify_deployment_event(payload: bytes, signature: str, signing_key: bytes) -> dict | None:
    expected = hmac.new(signing_key, payload, hashlib.sha256).hexdigest()
    if expected != signature:
        return None
    try:
        event = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid event payload') from exc
    if not isinstance(event, dict):
        raise ValueError('event must be an object')
    required = ('namespace', 'deployment', 'status', 'replicas')
    if any((field not in event for field in required)):
        raise ValueError('missing event field')
    if not all((isinstance(event[field], str) for field in ('namespace', 'deployment', 'status'))):
        raise ValueError('invalid event field')
    if event['status'] not in {'available', 'progressing', 'failed'}:
        raise ValueError('invalid status')
    if isinstance(event['replicas'], bool) or not isinstance(event['replicas'], int) or event['replicas'] < 0:
        raise ValueError('invalid replica count')
    return {'namespace': event['namespace'], 'deployment': event['deployment'], 'status': event['status'], 'replicas': event['replicas'], 'signature': signature}

