import ast
import operator

def import_records(records: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval')
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def evaluate(node, values):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, values)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool, type(None))):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for item in node.values:
                    result = evaluate(item, values)
                    if not result:
                        return result
                return result
            result = False
            for item in node.values:
                result = evaluate(item, values)
                if result:
                    return result
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for operation, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator, values)
                if type(operation) not in comparisons or not comparisons[type(operation)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
            arguments = [evaluate(arg, values) for arg in node.args]
            return min(*arguments) if node.func.id == 'min' else max(*arguments)
        raise ValueError('unsupported expression')
    return [record for record in records if evaluate(tree, record)]

import xml.etree.ElementTree as ET

def plan_batches(xml_text: str) -> list[tuple[int, str, int]]:
    root = ET.fromstring(xml_text)
    batches = []
    for element in root.findall('batch'):
        batches.append((int(element.attrib['oven']), element.attrib['product'], int(element.attrib['quantity'])))
    return sorted(batches, key=lambda item: (item[0], item[1]))

