import xml.sax.handler

class BatchHandler(xml.sax.handler.ContentHandler):

    def __init__(self) -> None:
        super().__init__()
        self.batches = []

    def startElement(self, name, attrs):
        if name == 'batch':
            self.batches.append((int(attrs['oven']), attrs['product'], int(attrs['quantity'])))

def plan_batches(xml_text: str) -> list[tuple[int, str, int]]:
    handler = BatchHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    parser.parse(io.StringIO(xml_text))
    return sorted(handler.batches, key=lambda item: (item[0], item[1]))

