import hashlib
import hmac
import os

def create_signature_record(signer: str, pin: str, payload: str) -> dict:
    if not signer or not pin:
        raise ValueError('signer and pin are required')
    salt = os.urandom(16)
    pin_hash = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    payload_hash = hashlib.sha256(payload.encode()).hexdigest()
    return {'signer': signer, 'pin_hash': salt.hex() + ':' + pin_hash.hex(), 'payload_hash': payload_hash}

def verify_signature(record: dict, pin: str, payload: str) -> bool:
    try:
        salt_text, digest_text = record['pin_hash'].split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected_pin = bytes.fromhex(digest_text)
        actual_pin = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        expected_payload = record['payload_hash']
    except (KeyError, TypeError, ValueError):
        return False
    actual_payload = hashlib.sha256(payload.encode()).hexdigest()
    return hmac.compare_digest(actual_pin, expected_pin) and hmac.compare_digest(actual_payload, expected_payload)

