import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, values)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name) and node.id in values:
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        operation = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
        return operation(left, right)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        checks = []
        for operation, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, values)
            fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(operation))
            if fn is None:
                raise ValueError
            checks.append(fn(left, right))
            left = right
        return all(checks)
    raise ValueError

def select_invoices(invoices: list[dict], rule: str) -> tuple[list[str], float]:
    try:
        tree = ast.parse(rule, mode='eval')
    except (SyntaxError, TypeError):
        raise ValueError
    selected = []
    total = 0.0
    for invoice in invoices:
        values = {key: invoice[key] for key in ('id', 'amount', 'overdue_days', 'priority')}
        try:
            matches = _evaluate(tree, values)
        except (KeyError, TypeError, ZeroDivisionError, ValueError, NameError):
            raise ValueError
        if matches:
            selected.append(invoice['id'])
            total += invoice['amount']
    return (selected, float(total))

