import hashlib
import hmac
import json

def authorize_dispatch(body: str, signature: str, secret: str) -> list[dict]:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(data, dict) or not isinstance(data.get('site'), str) or (not isinstance(data.get('commands'), list)):
        raise ValueError('invalid body')
    commands = []
    for command in data['commands']:
        if not isinstance(command, dict):
            raise ValueError('invalid command')
        battery = command.get('battery')
        target = command.get('target_kw')
        if not isinstance(battery, str) or not battery or isinstance(target, bool) or (not isinstance(target, (int, float))) or (not -100 <= target <= 100):
            raise ValueError('invalid command')
        commands.append(command)
    return sorted(commands, key=lambda command: command['battery'])

