import secrets
import string

def generate_provisioning_code(device_id: str, length: int=12) -> str:
    if not isinstance(device_id, str) or not device_id:
        raise ValueError('invalid device id')
    if not all((char.isascii() and (char.isalnum() or char == '-') for char in device_id)):
        raise ValueError('invalid device id')
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = string.ascii_uppercase.replace('I', '').replace('O', '') + '23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'{device_id.upper()}-{code}'

